INSERT INTO "report_versions" ("id", "report_id", "version", "docx_path", "snapshot_json", "created_by", "created_at") VALUES
('01M4D6CN5H88WCN12PX6G8JTHC', '01M4D6CC3BT2XH6VH2PMJ9V1GN', 1, 'reports/module/01M4D6CC3BT2XH6VH2PMJ9V1GN-en.docx', '{"model":{"request":{"reportId":"01M4D6CC3BT2XH6VH2PMJ9V1GN","typeCode":"org_annual_report","family":"public","period":{"kind":"year","year":2026,"label":{"en":"2026","ar":"2026"}},"scope":{"kind":"org","id":null,"code":null,"label":{"en":"Programme Office","ar":"مكتب البرنامج"}},"audience":"public","languageMode":"both","sectionCodes":["cover","contents","foreword","year_at_a_glance","mandate_governance","nes3_outcomes_overview","initiatives_progress","statistics_highlights","international_indices","events_partnerships","outlook","sources_appendix","closing"],"classification":1,"requestedBy":"01M4D6BGH96DBS87XWT8FQFFGW"},"typeName":{"en":"Annual Environment Report","ar":"التقرير البيئي السنوي"},"title":{"en":"Annual Environment Report 2026","ar":"التقرير البيئي السنوي 2026"},"subtitle":{"en":"Programme Office","ar":"مكتب البرنامج"},"periodLabel":{"en":"2026","ar":"2026"},"yearMark":"2026","classification":1,"generatedAt":"2026-10-08T07:24:27.226Z","preparedBy":{"en":"Abdullah Al-Harbi","ar":"عبدالله الحربي"},"sections":[{"code":"cover","title":{"en":"Annual Environment Report","ar":"التقرير البيئي السنوي"},"lead":{"en":"Programme Office","ar":"مكتب البرنامج"},"keyFigure":{"value":"18/23","label":{"en":"targets on track","ar":"مستهدفات على المسار"}},"layout":"cover","blocks":[],"sources":[],"meta":{"subtitle":{"en":"Programme Office","ar":"مكتب البرنامج"},"period":{"kind":"year","year":2026,"label":{"en":"2026","ar":"2026"}}}},{"code":"contents","title":{"en":"Contents","ar":"المحتويات"},"layout":"contents","blocks":[],"sources":[]},{"code":"foreword","title":{"en":"Foreword","ar":"التصدير"},"lead":{"en":"A word from the Secretary General on 2026.","ar":"كلمة الأمين العام عن 2026."},"layout":"opener","blocks":[{"kind":"paragraph","text":{"en":"It is my pleasure to present the Annual Environment Report for 2026. The Programme Office carried 38 initiatives and 64 projects through the year, and 18 of the 23 national targets we track stand on track today.","ar":"يسرني أن أقدم التقرير البيئي السنوي عن 2026. لقد حمل مكتب البرنامج 38 مبادرة و64 مشروعاً عبر العام، ويقف اليوم 18 من أصل 23 مستهدفاً وطنياً نتابعه على المسار الصحيح."}},{"kind":"paragraph","text":{"en":"Across the 24 international indices we follow, Saudi Arabia improved in 1, held steady in 22 and declined in 1, leading the Gulf Cooperation Office in 0 of them. Each movement is read in this report against the evidence behind it, not as a headline.","ar":"وفي المؤشرات الدولية الـ24 التي نتابعها، تحسنت السعودية في 1 منها، وحافظت على موقعها في 22، وتراجعت في 1، وتصدرت دول مجلس التعاون الخليجي في 0 منها. ويقرأ هذا التقرير كل تحرك في ضوء الشواهد الكامنة وراءه، لا بوصفه عنواناً."}},{"kind":"paragraph","text":{"en":"The 8 status updates recorded during the year and the 32 lessons our teams documented are the institutional memory this Office builds on. I thank every directorate and partner whose work these pages record, and I commend the report to its readers.","ar":"إن تحديثات الحالة الـ8 المسجلة خلال العام والدروس الـ32 التي وثقتها فرقنا هي الذاكرة المؤسسية التي يبني عليها هذا المكتب. وأشكر كل إدارة وشريك سجلت هذه الصفحات عملهم، وأوصي القراء بهذا التقرير."}},{"kind":"paragraph","style":"note","text":{"en":"Draft prepared by EnviroAI for the Secretary General''s review; the signed text replaces this page.","ar":"مسودة أعدها EnviroAI لمراجعة الأمين العام؛ ويحل النص الموقّع محل هذه الصفحة."}}],"sources":[{"n":1,"title":"EnviroAI Living Strategy","detail":"edition nes3, nodes, KPIs and status updates"},{"n":2,"title":"EnviroAI index forecasts","detail":"method v1, Monte Carlo over the index''s own history; an estimate, not a published value"},{"n":3,"title":"EnviroAI Indices board","detail":"Saudi Arabia''s latest movements"},{"n":4,"title":"EnviroAI Learning Room","detail":"published and verified lessons"}],"needsEditing":true,"meta":{"live":false,"draftedFor":"Secretary General"},"numeral":"01"},{"code":"year_at_a_glance","title":{"en":"The year at a glance","ar":"العام في لمحة"},"lead":{"en":"2026 in eight numbers.","ar":"2026 في ثمانية أرقام."},"layout":"glance","blocks":[{"kind":"kpis","items":[{"label":{"en":"Targets on track","ar":"مستهدفات على المسار"},"value":"18/23","tone":"navy"},{"label":{"en":"Initiatives","ar":"المبادرات"},"value":"38","tone":"ink"},{"label":{"en":"Projects","ar":"المشاريع"},"value":"64","delta":"4 completed","tone":"ink"},{"label":{"en":"Status updates","ar":"تحديثات الحالة"},"value":"8","tone":"teal"},{"label":{"en":"Deliverables received","ar":"مخرجات مستلمة"},"value":"21","tone":"teal"},{"label":{"en":"Lessons documented","ar":"دروس موثقة"},"value":"32","tone":"aqua"},{"label":{"en":"Signals accepted","ar":"إشارات مقبولة"},"value":"30","tone":"aqua"},{"label":{"en":"Indices improving","ar":"مؤشرات في تحسن"},"value":"1/24","delta":"1 declining","tone":"navy"}]},{"kind":"paragraph","text":{"en":"The Office closed 2026 with 18 of 23 tracked targets on track, 38 initiatives and 64 projects in delivery, of which 4 are completed and 6 are at risk or delayed.","ar":"أنهى المكتب 2026 وقد كان 18 من أصل 23 مستهدفاً متابعاً على المسار، مع 38 مبادرة و64 مشروعاً قيد التنفيذ، اكتمل منها 4 وتعرض 6 للخطر أو التأخر."}},{"kind":"paragraph","text":{"en":"During the year the teams recorded 8 status updates and received 21 deliverables; 32 lessons were documented and 30 external signals were accepted onto the radar, while Saudi Arabia improved in 1 of the 24 international indices tracked.","ar":"وخلال العام سجلت الفرق 8 تحديثاً للحالة واستلمت 21 مخرجاً؛ ووُثق 32 درساً وقُبلت 30 إشارة خارجية على الرادار، بينما تحسنت السعودية في 1 من المؤشرات الدولية الـ24 المتابعة."}},{"kind":"chart","chart":{"type":"bar","title":{"en":"Status updates per month","ar":"تحديثات الحالة شهرياً"},"series":[{"name":{"en":"Updates","ar":"التحديثات"},"role":"primary","points":[{"x":"2026-01","y":0},{"x":"2026-02","y":0},{"x":"2026-03","y":0},{"x":"2026-04","y":0},{"x":"2026-05","y":0},{"x":"2026-06","y":0},{"x":"2026-07","y":0},{"x":"2026-08","y":0},{"x":"2026-09","y":3},{"x":"2026-10","y":5}]}],"source":{"en":"EnviroAI Living Strategy","ar":"الاستراتيجية الحية في EnviroAI"}}}],"sources":[{"n":1,"title":"EnviroAI Living Strategy","detail":"edition nes3, nodes, KPIs and status updates"},{"n":2,"title":"EnviroAI Institutional Memory","detail":"documents and deliverables"},{"n":3,"title":"EnviroAI Learning Room","detail":"published and verified lessons"},{"n":4,"title":"EnviroAI Signals Radar","detail":"accepted signals"},{"n":5,"title":"EnviroAI Indices board","detail":"Saudi Arabia''s latest movements"}],"meta":{"live":false,"tiles":8},"numeral":"02"},{"code":"mandate_governance","title":{"en":"Mandate and governance","ar":"الولاية والحوكمة"},"lead":{"en":"What Office of the Programme Director is mandated to do and how it is governed.","ar":"ما أُنيط بـمكتب مدير البرنامج وكيف تُحكم."},"layout":"body","blocks":[{"kind":"paragraph","text":{"en":"Office of the Programme Director is headed by Asma Al-Ajlan, Head of Office and comprises 7 units, with 41 staff recorded in EnviroAI.","ar":"مكتب مدير البرنامج يرأسها أسماء العجلان، رئيس المكتب وتضم 7 وحدات، ويعمل بها 41 موظفاً مسجلاً في EnviroAI."}},{"kind":"paragraph","text":{"en":"The Office''s institutional strategy, Programme Office Institutional Strategy 2025 to 2030, sets out 5 values and is governed through 3 bodies; the strategy on record is illustrative until the approved text replaces it.","ar":"وتحدد الاستراتيجية المؤسسية للمكتب، الاستراتيجية المؤسسية لمكتب البرنامج 2025 - 2030، 5 قيم، وتُحكم من خلال 3 هيئات؛ والاستراتيجية المسجلة استرشادية إلى أن يحل النص المعتمد محلها."}},{"kind":"quote","text":{"en":"Leads the Office, chairs its executive committee and answers to the Programme Steering Committee for delivery of the National Environment Strategy. Sets priorities across sectors and represents the Office with national entities.","ar":"يقود المكتب ويرأس لجنته التنفيذية ويرفع إلى اللجنة التوجيهية للبرنامج عن تنفيذ الاستراتيجية الوطنية للبيئة. يحدد الأولويات بين القطاعات ويمثل المكتب لدى الجهات الوطنية."},"attribution":{"en":"Published mandate, Office of the Programme Director","ar":"الولاية المنشورة، مكتب مدير البرنامج"}},{"kind":"table","caption":{"en":"Units under Office of the Programme Director","ar":"الوحدات التابعة لـمكتب مدير البرنامج"},"columns":[{"en":"Unit","ar":"الوحدة"},{"en":"Level","ar":"المستوى"},{"en":"Staff","ar":"الموظفون"}],"rows":[[{"en":"Strategy and Performance Sector","ar":"قطاع الاستراتيجية والأداء"},{"en":"sector","ar":"sector"},{"en":"20","ar":"20"}],[{"en":"Regulatory Affairs Sector","ar":"قطاع الشؤون التنظيمية"},{"en":"sector","ar":"sector"},{"en":"0","ar":"0"}],[{"en":"Data and Knowledge Sector","ar":"قطاع البيانات والمعرفة"},{"en":"sector","ar":"sector"},{"en":"12","ar":"12"}],[{"en":"Digital Transformation Office","ar":"مكتب التحول الرقمي"},{"en":"office","ar":"office"},{"en":"0","ar":"0"}],[{"en":"Partnerships and International Commitments","ar":"إدارة الشراكات والالتزامات الدولية"},{"en":"department","ar":"department"},{"en":"0","ar":"0"}],[{"en":"Communications","ar":"إدارة الاتصال"},{"en":"department","ar":"department"},{"en":"0","ar":"0"}],[{"en":"Corporate Services Sector","ar":"قطاع الخدمات المؤسسية"},{"en":"sector","ar":"sector"},{"en":"4","ar":"4"}]],"align":["start","start","end"]},{"kind":"callout","title":{"en":"Vision","ar":"الرؤية"},"text":{"en":"A reference institution whose strategy, environmental data and foresight set the professional standard for environment, water and agriculture work in Saudi Arabia.","ar":"مؤسسة مرجعية تضع استراتيجيتها وبياناتها البيئية واستشرافها المعيار المهني لأعمال البيئة والمياه والزراعة في المملكة العربية السعودية."},"tone":"navy"},{"kind":"callout","title":{"en":"Mission","ar":"الرسالة"},"text":{"en":"We steer the National Environment Strategy, monitor its delivery, keep environmental data trustworthy and read the future, so that choices on water, food, climate, land, waste and air rest on evidence rather than assumption. We work alongside every entity in the sector, and with partners in universities, the private sector and the community, to turn national priorities into plans that are delivered and measured.","ar":"نقود الاستراتيجية الوطنية للبيئة ونتابع تنفيذها، ونحافظ على موثوقية البيانات البيئية ونستشرف المستقبل، لتستند الخيارات في المياه والغذاء والمناخ والأراضي والنفايات والهواء إلى الأدلة لا إلى الافتراضات. ونعمل جنباً إلى جنب مع جهات القطاع كافة، ومع شركائنا في الجامعات والقطاع الخاص والمجتمع، لتحويل الأولويات الوطنية إلى خطط قابلة للتنفيذ والقياس."},"tone":"teal"},{"kind":"heading","level":3,"text":{"en":"Values","ar":"القيم"}},{"kind":"bullets","items":[{"en":"Evidence first","ar":"الأدلة أولاً"},{"en":"Professional independence","ar":"الاستقلالية المهنية"},{"en":"Partnership in delivery","ar":"الشراكة في التنفيذ"},{"en":"Foresight as a habit","ar":"الاستشراف عادة مؤسسية"},{"en":"Knowledge that stays","ar":"معرفة تبقى في المؤسسة"}]},{"kind":"table","caption":{"en":"Governance bodies","ar":"هيئات الحوكمة"},"columns":[{"en":"Body","ar":"الهيئة"},{"en":"Role","ar":"الدور"},{"en":"Cadence","ar":"الوتيرة"}],"rows":[[{"en":"Strategy Steering Committee","ar":"لجنة توجيه الاستراتيجية"},{"en":"Chaired by the Programme Director, the committee owns the institutional strategy: it approves the annual targets, reviews the scorecard and the risk register each quarter, decides on the reallocation of budget and people between projects, and escalates blockers that departments cannot resolve on their own.","ar":"برئاسة مدير البرنامج، تتولى اللجنة ملكية الاستراتيجية المؤسسية: تعتمد المستهدفات السنوية، وتستعرض بطاقة الأداء وسجل المخاطر كل ربع سنة، وتبت في إعادة توزيع الموازنة والكوادر بين المشاريع، وتعالج المعوقات التي تعجز الإدارات عن حلها بمفردها."},{"en":"quarterly","ar":"quarterly"}],[{"en":"Strategy Office","ar":"مكتب الاستراتيجية"},{"en":"The Strategy Development department acts as the Strategy Office. It maintains the results chain and the indicator cards, collects actuals on each indicator''s cadence, challenges the quality of the evidence behind a reported figure, prepares the quarterly pack for the steering committee, and keeps the change log of every amendment to the strategy.","ar":"تقوم إدارة تطوير الاستراتيجية بدور مكتب الاستراتيجية. فتتعهد سلسلة النتائج وبطاقات المؤشرات، وتجمع القيم الفعلية وفق دورية كل مؤشر، وتراجع جودة الأدلة وراء أي رقم مرفوع، وتُعدّ الحزمة الربعية للجنة التوجيهية، وتحتفظ بسجل التغييرات لكل تعديل على الاستراتيجية."},{"en":"monthly","ar":"monthly"}],[{"en":"Department Focal Points Network","ar":"شبكة ضباط الاتصال في الإدارات"},{"en":"One named focal point in every department carries the strategy inside the department: updating project and activity status, entering actuals against indicators the department owns, and raising risks and dependencies early. The network meets monthly and is the Strategy Office''s working channel into the departments.","ar":"يتولى ضابط اتصال مسمّى في كل إدارة حمل الاستراتيجية داخل إدارته: تحديث حالة المشاريع والأنشطة، وإدخال القيم الفعلية للمؤشرات التي تملكها الإدارة، ورفع المخاطر والاعتماديات مبكراً. وتجتمع الشبكة شهرياً وهي قناة عمل مكتب الاستراتيجية مع الإدارات."},{"en":"monthly","ar":"monthly"}]]}],"sources":[{"n":1,"title":"Programme Office organisational structure","detail":"enviroai.demo, as recorded in EnviroAI","url":""},{"n":2,"title":"EnviroAI Programme Strategy, illustrative data","detail":"Internal"}],"meta":{"live":false,"illustrative":true},"numeral":"03"},{"code":"nes3_outcomes_overview","title":{"en":"NES themes overview","ar":"نظرة عامة على محاور الاستراتيجية الوطنية للبيئة"},"lead":{"en":"National Environment Strategy (NES) Delivery Plan 2024-2030: 7 outcomes, one picture.","ar":"خطة تنفيذ الاستراتيجية الوطنية للبيئة 2024-2030: 7 نتائج في صورة واحدة."},"layout":"body","blocks":[{"kind":"paragraph","text":{"en":"National Environment Strategy (NES) Delivery Plan 2024-2030 is organised around 7 national outcomes carrying 23 targets, 38 initiatives and 64 projects; 18 of 23 targets are on track.","ar":"تنتظم خطة تنفيذ الاستراتيجية الوطنية للبيئة 2024-2030 حول 7 نتائج وطنية تحمل 23 مستهدفاً و38 مبادرة و64 مشروعاً؛ و18 من أصل 23 مستهدفاً على المسار."}},{"kind":"paragraph","text":{"en":"O2 leads with 100% of its targets on track, while O6 stands at 50% and carries the most delivery attention in the period.","ar":"تتصدر O2 بنسبة 100% من مستهدفاتها على المسار، بينما تقف O6 عند 50% وتستأثر بأكبر قدر من الاهتمام التنفيذي في الفترة."}},{"kind":"table","caption":{"en":"Outcomes and their delivery structure","ar":"النتائج وهيكل تنفيذها"},"columns":[{"en":"Code","ar":"الرمز"},{"en":"Outcome","ar":"النتيجة"},{"en":"Targets","ar":"المستهدفات"},{"en":"Initiatives","ar":"المبادرات"},{"en":"Projects","ar":"المشاريع"},{"en":"Progress","ar":"التقدم"},{"en":"Lead","ar":"الجهة المسؤولة"}],"rows":[[{"en":"O1","ar":"O1"},{"en":"Water Security","ar":"الأمن المائي"},{"en":"4","ar":"4"},{"en":"7","ar":"7"},{"en":"10","ar":"10"},{"en":"50%","ar":"50%"},{"en":"Ministry of Environment, Water and Agriculture","ar":"وزارة البيئة والمياه والزراعة"}],[{"en":"O2","ar":"O2"},{"en":"Agriculture and Food Security","ar":"الأمن الغذائي والزراعة"},{"en":"3","ar":"3"},{"en":"5","ar":"5"},{"en":"8","ar":"8"},{"en":"100%","ar":"100%"},{"en":"Ministry of Environment, Water and Agriculture","ar":"وزارة البيئة والمياه والزراعة"}],[{"en":"O3","ar":"O3"},{"en":"Biodiversity and Land","ar":"التنوع الأحيائي والأراضي"},{"en":"3","ar":"3"},{"en":"7","ar":"7"},{"en":"14","ar":"14"},{"en":"67%","ar":"67%"},{"en":"National Center for Wildlife","ar":"المركز الوطني لتنمية الحياة الفطرية"}],[{"en":"O4","ar":"O4"},{"en":"Waste and Circular Economy","ar":"النفايات والاقتصاد الدائري"},{"en":"3","ar":"3"},{"en":"4","ar":"4"},{"en":"7","ar":"7"},{"en":"100%","ar":"100%"},{"en":"National Center for Waste Management","ar":"المركز الوطني لإدارة النفايات"}],[{"en":"O5","ar":"O5"},{"en":"Air Quality","ar":"جودة الهواء"}