INSERT INTO "risks" ("id", "title_en", "title_ar", "likelihood", "impact", "owner_user_id", "node_id", "mitigation_en", "mitigation_ar", "status", "created_at") VALUES
('01M4D6BHRZM0VV37N963B7VMDG', 'Delays in data sharing between regulators', 'تأخر تبادل البيانات بين الجهات التنظيمية', 4, 4, '01M4D6BGHAKBD28V6BPQ7S7XE3', NULL, 'Formalise data sharing agreements with clear timelines and escalation paths.', 'إضفاء الطابع الرسمي على اتفاقيات تبادل البيانات مع جداول زمنية ومسارات تصعيد واضحة.', 'mitigating', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZM2FW1SFMATEKVYQD', 'Scarcity of specialised data and environmental science talent', 'ندرة الكفاءات المتخصصة في البيانات والعلوم البيئية', 4, 3, '01M4D6BHEQKPFW1H83BFHK8QB8', NULL, 'Expand training partnerships and fellowships with Saudi universities to build local pipelines.', 'توسيع شراكات التدريب والزمالات مع الجامعات السعودية لبناء مسارات كفاءات محلية.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZ9M0TQN3FBNQNHYPP', 'Reprioritisation of programme funding', 'إعادة ترتيب أولويات تمويل البرنامج', 3, 5, '01M4D6BGH96DBS87XWT8FQFFGW', NULL, 'Maintain a transparent prioritisation framework tied to theme impact scores.', 'الحفاظ على إطار شفاف لترتيب الأولويات مرتبط بدرجات أثر المحاور.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZEXXRTVZBK7D14RT2', 'Vendor lock-in on core monitoring systems', 'الارتهان لمورد واحد في نظم الرصد الأساسية', 2, 4, '01M4D6BHESYXB11S441J7G02R7', NULL, 'Require open standards and data portability clauses in all new technology contracts.', 'اشتراط المعايير المفتوحة وبنود قابلية نقل البيانات في جميع عقود التقنية الجديدة.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZYFQPP4HJYWWDGT4B', 'Cyber incident affecting monitoring data integrity', 'حادث سيبراني يؤثر في سلامة بيانات الرصد', 1, 5, '01M4D6BHENT806953T1KMXG22P', NULL, 'Strengthen backup protocols, access controls and incident response drills.', 'تعزيز بروتوكولات النسخ الاحتياطي وضوابط الوصول وتمارين الاستجابة للحوادث.', 'mitigating', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZ03QERFNE6V25RJGT', 'Methodology changes at international index providers', 'تغيير المنهجية لدى مزودي المؤشرات الدولية', 3, 1, '01M4D6BHENXFYQ2E4HXXWJ52XS', NULL, 'Monitor provider announcements closely and pre-brief teams on likely methodology shifts.', 'متابعة إعلانات المزودين عن كثب وإحاطة الفرق مسبقاً بتغييرات المنهجية المحتملة.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZGE9F108A5SBM56Y5', 'Incomplete response rates in household surveys', 'انخفاض معدلات الاستجابة في المسوح الأسرية', 3, 3, '01M4D6BHETEQ14RFJ4M9ZHBW8N', NULL, 'Diversify survey channels and run awareness campaigns ahead of fieldwork.', 'تنويع قنوات المسح وتنفيذ حملات توعية قبل العمل الميداني.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHRZWJCETYHJDPM3QEVS', 'Overlapping mandates between delivery entities', 'تداخل الاختصاصات بين جهات التنفيذ', 2, 2, '01M4D6BGH96DBS87XWT8FQFFGW', NULL, 'Clarify roles through updated governance charters for each delivery entity.', 'توضيح الأدوار عبر مواثيق حوكمة محدثة لكل جهة تنفيذ.', 'mitigating', '2026-10-08T07:23:58.764Z'),
('01M4D6BHS0FJK6SN917D2JBCW1', 'Slower than expected renewable energy project delivery', 'تباطؤ تنفيذ مشاريع الطاقة المتجددة عن المتوقع', 2, 3, '01M4D6BHF3952678NKGW8E66VY', NULL, 'Track project milestones monthly and escalate delivery risks early.', 'متابعة معالم المشاريع شهرياً وتصعيد مخاطر التنفيذ مبكراً.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHS05N53J3576BCG4902', 'Public misinterpretation of published indicators', 'سوء تفسير الجمهور للمؤشرات المنشورة', 5, 2, '01M4D6BGHA1ANAZV0TK6CR8SAW', NULL, 'Publish plain-language explainers alongside technical releases.', 'نشر شروح مبسطة إلى جانب الإصدارات الفنية.', 'open', '2026-10-08T07:23:58.764Z'),
('01M4D6BHS0K45JKZ8F6AXHTNWX', 'Fragmented environmental data standards across entities', 'تشتت معايير البيانات البيئية بين الجهات', 5, 4, '01M4D6BGHAKBD28V6BPQ7S7XE3', NULL, 'Accelerate rollout of shared data standards across remaining entities.', 'تسريع تطبيق معايير البيانات المشتركة في الجهات المتبقية.', 'mitigating', '2026-10-08T07:23:58.764Z'),
('01M4D6BHS0VGE56G4REDP27K0Z', 'Low awareness of foresight tools among delivery teams', 'ضعف الوعي بأدوات الاستشراف لدى فرق التنفيذ', 2, 1, '01M4D6BHF6ZPK7Q7DD57GF2GH6', NULL, 'Run regular foresight capacity-building workshops for focal points.', 'تنظيم ورش منتظمة لبناء قدرات الاستشراف لدى منسقي الفرق.', 'open', '2026-10-08T07:23:58.764Z');
